# p2 rule: fill zeros strictly between two same-colored frames' border cells along a row/col
# where the zero gap lies BETWEEN them. Check on demos with this exact rule.
def solve(I,border):
    H,W=len(I),len(I[0]); boxes=[]
    h=5
    for r in range(H-h+1):
        for c in range(W-h+1):
            b=[[I[i][j] for j in range(c,c+h)] for i in range(r,r+h)]
            if all(b[0][j]==b[-1][j]==border for j in range(h)) and all(b[i][0]==b[i][-1]==border for i in range(h)):
                cores=set(b[i][j] for i in range(1,h-1) for j in range(1,h-1))
                if len(cores)==1 and list(cores)[0]!=border:
                    boxes.append((r,c,list(cores)[0]))
    out=[row[:] for row in I]
    anchors=defaultdict(list)
    for r,c,v in boxes: anchors[v].append((r,c))
    for v,pts in anchors.items():
        rs=[p[0] for p in pts]; cs_=[p[1] for p in pts]
        r0,r1=min(rs),max(rs); c0,c1=min(cs_),max(cs_)
        # vertical spans per col: anchors in same col, span rows between; horizontal same row
        byrow=defaultdict(list); bycol=defaultdict(list)
        for r,c,vv in [(a[0],a[1],v) for a in pts]:
            byrow[r].append(c); bycol[c].append(r)
        changed=True
        while changed:
            changed=False
            for rc,cols in byrow.items():
                cols=sorted(cols); 
                # only if adjacent-in-list anchors are same color... but here all anchors of v share color v!
                for c in range(min(cols)+1,max(cols)):
                    if out[rc][c]==0:
                        out[rc][c]=v; changed=True
            for cc,rows in bycol.items():
                rows=sorted(rows)
                for r in range(min(rows)+1,max(rows)):
                    if out[r][cc]==0:
                        out[r][cc]=v; changed=True
    return out

