def f(I,border):
    H,W=len(I),len(I[0])
    win=[]
    for r in range(H-4):
        for c in range(W-4):
            b=[[I[i][j] for j in range(c,c+5)] for i in range(r,r+5)]
            if all(b[i][0]==b[i][4]==border and b[0][j]==b[4][j]==border for i in range(5) for j in range(5)):
                cs=tuple(sorted({b[i][j] for i in range(1,4) for j in range(1,4)}))
                if len(cs)==1 and list(cs)[0]!=border:
                    win.append((r,c,list(cs)[0]))
    out=[row[:] for row in I]
    cnt=Counter(v for _,_,v in win)
    major=cnt.most_common(1)[0][0]
    by=defaultdict(list)
    for p in win: by[p[2]].append(p[:2])
    for v,p in by.items():
        if v==major: continue
        pts=p
        rs=[q[0] for q in pts]; cs_=[q[1] for q in pts]
        r0,r1=min(rs),max(rs); c0,c1=min(cs_),max(cs_)
        for cc in range(c0,c1+1):
            for r in (r0,r1):
                if out[r][cc]==0: out[r][cc]=v
        for rr in range(r0,r1+1):
            for cc in (c0,c1):
                if out[rr][cc]==0: out[rr][cc]=v
    return out

